def R(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def W(p, s):
    with open(p, "w", encoding="utf-8") as f:
        f.write(s)


def REP(path, old, new, tag, count=1):
    s = R(path)
    if s.count(old) != count:
        raise SystemExit("gn_ae: anchor %s not unique (%d, expected %d) in %s"
                         % (tag, s.count(old), count, path))
    W(path, s.replace(old, new))
    print("AE: patched %s (%s)" % (path, tag))


# ===========================================================================
# 1 : rewrite the bundled HTML UI with the corrected behaviour layer.
#     head/body (all CSS + markup) are byte-for-byte identical to v4.7.
# ===========================================================================
os.makedirs(ASSETS, exist_ok=True)
W(ASSETS + "/offex_ui.html", base64.b64decode(HTML_B64).decode("utf-8"))
print("AE: wrote assets/offex_ui.html (%d bytes)" % os.path.getsize(ASSETS + "/offex_ui.html"))

# ===========================================================================
# 2 : MainActivity.java - make bridge/JS failures visible.
#     (a) WebChromeClient.onConsoleMessage -> logcat, so console.error and
#         uncaught page errors are no longer silent;
#     (b) a log(String) bridge method the page can call from window.onerror.
# ===========================================================================
M = J + "/MainActivity.java"

REP(M,
    '            webUi.addJavascriptInterface(new OffexBridge(), "OffexNative");',
    '            webUi.setWebChromeClient(new android.webkit.WebChromeClient(){\n'
    '                @Override public boolean onConsoleMessage(android.webkit.ConsoleMessage m){\n'
    '                    try { android.util.Log.i("OffexUI", m.message() + " @" + m.lineNumber()); } catch(Exception e){}\n'
    '                    return true;\n'
    '                }\n'
    '            });\n'
    '            webUi.addJavascriptInterface(new OffexBridge(), "OffexNative");',
    "webchrome console")

REP(M,
    '        @JavascriptInterface public String getState(){ return stateJson; }',
    '        @JavascriptInterface public void log(final String msg){ try { android.util.Log.i("OffexUI", msg == null ? "" : msg); } catch(Exception e){} }\n'
    '        @JavascriptInterface public String getState(){ return stateJson; }',
    "bridge log")

# ===========================================================================
# 3 : version bump 4.7 -> 4.8 (self-version + about strings).
# ===========================================================================
REP(J + "/Config.java",
    '            if(latest.equals("4.7")) return;',
    '            if(latest.equals("4.8")) return;',
    "self-version 4.8")

REP(J + "/SupportActivity.java",
    '    public static final String VERSION = "4.7";',
    '    public static final String VERSION = "4.8";',
    "support self-version 4.8")

for loc in ["", "-hi", "-es", "-pt", "-ar", "-ru", "-in"]:
    p = RES + "/values" + loc + "/strings.xml"
    if not os.path.exists(p):
        continue
    s = R(p)
    s2 = re.sub(r'(name="about_version">[^<]*?)4\.7(<)', r"\g<1>4.8\g<2>", s)
    if s2 == s:
        print("AE: (skip) about_version 4.7 not present in %s" % p)
    else:
        W(p, s2)
        print("AE: patched %s (about_version 4.8)" % p)

print("AE: done")
